import { pathToFileURL } from 'node:url';
import { isDeepStrictEqual } from 'node:util';

const PROJ = 'C:/Users/user/AppData/Local/Temp/skill-eval-5UJvbu/';
const req = createRequire(import.meta.url);
const LODASH = 'C:/Users/user/AppData/Local/Temp/claude/C--Users-user-AppData-Local-Temp-skill-eval-q3zqYY/027e5162-2014-4f47-95e5-4c8af275ed5c/scratchpad/node_modules/lodash/';

// bundle the migrated file with the project's esbuild
const esbuild = createRequire(PROJ + 'package.json')('esbuild');
const out = 'C:/Users/user/AppData/Local/Temp/claude/C--Users-user-AppData-Local-Temp-skill-eval-5UJvbu/d91f9f3c-9135-4626-9efd-cb743904ee3d/scratchpad/bundle.mjs';
await esbuild.build({ entryPoints: [PROJ + 'out/module.ts'], bundle: true, format: 'esm', platform: 'node', outfile: out, logLevel: 'silent' });
const M = await import(pathToFileURL(out).href);

// original behaviour, using lodash
const lmerge = req(LODASH + 'merge.js');
const lstart = req(LODASH + 'startCase.js');
const lempty = req(LODASH + 'isEmpty.js');
const O = {
  applyPatch: (b, p) => lmerge(b, p),
  toTitle: (k) => lstart(k),
  isBlank: (v) => lempty(v),
};

const clone = (x) => structuredClone(x);
const check = (name, args, label) => {
  const e = O[name](...clone(args));
  const a = M[name](...clone(args));
  const ok = isDeepStrictEqual(a, e);
  console.log(ok ? 'OK  ' : 'FAIL', label ?? name, JSON.stringify(args), '->', JSON.stringify(a));
  return ok;
};
// spec examples
let ok = true;
ok &= check('applyPatch', [{}, { enabled: 17 }]);
ok &= check('applyPatch', [{ limits: {}, enabled: '' }, { limits: { enabled: 63 }, enabled: '', layout: {} }]);
ok &= check('toTitle', ['Width.91-ApiWidth.']);
ok &= check('toTitle', ['Apiurl api_0-36']);
ok &= check('isBlank', ['red']);
ok &= check('isBlank', [[{ enabled: { theme: 'compact', enabled: 'blue' }, items: '' }, {}]]);

// randomized in-range sweep
const R = (n) => Math.floor(Math.random() * n);
const ALPHA = 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789   -_.';
const rs = () => Array.from({ length: R(41) }, () => ALPHA[R(ALPHA.length)]).join('');
let bad = 0;
for (let i = 0; i < 20000; i++) if (O.toTitle(rs()) !== M.toTitle(rs())) bad++; // placeholder, fixed below
bad = 0;
for (let i = 0; i < 20000; i++) { const s = rs(); if (!isDeepStrictEqual(M.toTitle(s), O.toTitle(s))) bad++; }
for (let i = 0; i < 20000; i++) { const v = [null, true, R(105) - 5, rs(), [rs()], { a: [1, { b: null }] }, [], {}][R(8)]; if (!isDeepStrictEqual(M.isBlank(clone(v)), O.isBlank(clone(v)))) bad++; }
console.log('random sweep mismatches:', bad);
console.log(ok && bad === 0 ? 'ALL GOOD' : 'MISMATCH PRESENT');

